import sys, time

L=('L',)
def size(t):
    c=t[0]
    if c=='V' or c=='L': return 1
    if c in 'QSA': return 1+size(t[1])
    return 1+size(t[1])+size(t[2])

def subst_rec(t,N,k):
    c=t[0]
    if c=='V':
        i=t[1]
        if i<k: return t
        if i==k: return lift_rec(N,0,k)
        return ('V',i-1)
    if c=='L': return t
    if c=='Q': return ('Q',subst_rec(t[1],N,k+1))
    if c=='S': return ('S',subst_rec(t[1],N,k))
    if c=='A': return ('A',subst_rec(t[1],N,k))
    return (c,subst_rec(t[1],N,k),subst_rec(t[2],N,k))
def subst(t,N): return subst_rec(t,N,0)
def lift_rec(t,k,n):
    c=t[0]
    if c=='V': return ('V',n+t[1] if k<=t[1] else t[1])
    if c=='L': return t
    if c=='Q': return ('Q',lift_rec(t[1],k+1,n))
    if c=='S': return ('S',lift_rec(t[1],k,n))
    if c=='A': return ('A',lift_rec(t[1],k,n))
    return (c,lift_rec(t[1],k,n),lift_rec(t[2],k,n))
def lift(t,n=1): return lift_rec(t,0,n)
def quant(n,t):
    for _ in range(n): t=('Q',t)
    return t

def gen_types(maxsize,maxvar):
    by={i:[] for i in range(1,maxsize+1)}
    by[1]=[L]+[('V',i) for i in range(maxvar)]
    for s in range(2,maxsize+1):
        cur=[]
        for t in by[s-1]:
            for c in 'QSA': cur.append((c,t))
        for i in range(1,s-1):
            j=s-1-i
            for a in by[i]:
                for b in by[j]:
                    cur.append(('F',a,b)); cur.append(('K',a,b))
        seen=set(); out=[]
        for t in cur:
            if t not in seen: seen.add(t); out.append(t)
        by[s]=out
    types=[]
    for s in range(1,maxsize+1): types+=by[s]
    return types

def bits(x):
    while x:
        b=x&-x; yield b.bit_length()-1; x-=b

def run(maxsize=4,maxvar=3):
    t0=time.time()
    types=gen_types(maxsize,maxvar); idx={t:i for i,t in enumerate(types)}; n=len(types)
    print("types",n,flush=True)
    reach=[0]*n
    def add(a,b):
        ia=idx.get(a); ib=idx.get(b)
        if ia is None or ib is None: return False
        if reach[ia]>>ib &1: return False
        reach[ia]|=1<<ib; return True
    atomic=[]
    def at(a,b):
        if size(a)<=maxsize and size(b)<=maxsize: atomic.append((a,b))
    for t in types: at(t,t)
    for u in types:
        at(L,('F',u,('S',u)))
        at(('Q',('S',u)),('S',('Q',u)))
        at(('Q',('A',u)),('A',('Q',u)))
        at(('Q',u),lift(u,1))
        for v in types:
            at(('Q',('K',u,v)),('K',('Q',u),('Q',v)))
            at(('Q',('F',u,v)),('F',('Q',u),('Q',v)))
            at(('S',u),('F',v,('K',u,v)))
            at(('K',L,u),('F',v,u))
            at(('A',('F',u,v)),('F',u,v))
        for v in types:
            at(('Q',u),subst(u,v))
    for a,b in atomic: add(a,b)
    print("atomic",sum(x.bit_count() for x in reach),"time",round(time.time()-t0,2),flush=True)
    it=0
    while True:
        it+=1
        old=sum(x.bit_count() for x in reach)
        # transitive closure
        for k in range(n):
            rk=reach[k]; bit=1<<k
            for i in range(n):
                if reach[i]&bit: reach[i]|=rk
        # structural
        # stem, asf, quant
        for a in range(n):
            ta=types[a]; ra=reach[a]
            for b in bits(ra):
                tb=types[b]
                add(('S',ta),('S',tb)); add(('A',ta),('A',tb)); add(('Q',ta),('Q',tb))
        # funty: for a with reach to b, and c->d
        for a in range(n):
            ta=types[a]
            for b in bits(reach[a]):
                tb=types[b]
                for c in range(n):
                    for d in bits(reach[c]):
                        add(('F',ta,types[c]),('F',tb,types[d]))
        # fork
        # iterate pairs (a,b) in reach; then product of desc
        for a in range(n):
            ta=types[a]
            for b in bits(reach[a]):
                tb=types[b]
                for c in range(n):
                    tc=types[c]
                    for d in bits(reach[c]):
                        add(('K',ta,tc),('K',tb,types[d]))
        new=sum(x.bit_count() for x in reach)
        print("iter",it,"pairs",new,"time",round(time.time()-t0,2),flush=True)
        if new==old: break
        if it>15: break
    # check L1
    bad=[]
    for i,ti in enumerate(types):
        if ti!=L: continue
        for j in bits(reach[i]):
            tj=types[j]
            if tj[0]!='F': continue
            a,r=tj[1],tj[2]
            ia=idx.get(('S',a)); ir=idx.get(r)
            ok = ia is not None and ir is not None and (reach[ia]>>ir)&1
            if not ok: bad.append((tj,('S',a),r, ia, ir))
    print("bad",len(bad),flush=True)
    for x in bad[:15]: print("BAD",x,flush=True)
    return types,reach,bad

if __name__=='__main__':
    run(int(sys.argv[1]),int(sys.argv[2]))

