// type: constructor code, children indices
struct T { int c; vector<int> ch; };
vector<T> U; map<array<int,3>,int> mp; // key: (c, ch0, ch1) -1 padded
int LEAFc=0,VARc=1,STEMc=2,FORKc=3,FUNTYc=4,ASFc=5,QUANTc=6;
int addT(int c, vector<int> ch){
    array<int,3> key={c, ch.size()>0?ch[0]:-1, ch.size()>1?ch[1]:-1};
    auto it=mp.find(key); if(it!=mp.end()) return it->second;
    int id=U.size(); U.push_back({c,ch}); mp[key]=id; return id;
}
