int sizeOf(int id);
int szMemo[100000];
int sizeOf(int id){ if(szMemo[id]) return szMemo[id]; int s=1; for(int x:U[id].ch) s+=sizeOf(x); return szMemo[id]=s; }
bool CLOSED=false;
