int mkFork(int a,int b){ if(a<0||b<0) return -1; if(CLOSED) return lookup(FORKc,{a,b}); return create(FORKc,{a,b});}
int mkFunty(int a,int b){ if(a<0||b<0) return -1; if(CLOSED) return lookup(FUNTYc,{a,b}); return create(FUNTYc,{a,b});}
int mkAsf(int a){ if(a<0) return -1; if(CLOSED) return lookup(ASFc,{a}); return create(ASFc,{a});}
int mkQuant(int a){ if(a<0) return -1; if(CLOSED) return lookup(QUANTc,{a}); return create(QUANTc,{a});}

int lift_rec(int t,int k,int n);
int lift_rec(int t,int k,int n){
    auto &x=U[t]; int c=x.c;
    if(c==VARc){ int i=x.ch[0]; return mkV(k<=i? n+i : i); }
    if(c==LEAFc) return mkLeaf();
    if(c==STEMc||c==ASFc) return c==STEMc? mkStem(lift_rec(x.ch[0],k,n)) : mkAsf(lift_rec(x.ch[0],k,n));
    if(c==FORKc||c==FUNTYc) return c==FORKc? mkFork(lift_rec(x.ch[0],k,n),lift_rec(x.ch[1],k,n)) : mkFunty(lift_rec(x.ch[0],k,n),lift_rec(x.ch[1],k,n));
    if(c==QUANTc) return mkQuant(lift_rec(x.ch[0],k+1,n));
    assert(false);
}
