    if(c==LEAFc) return mkLeaf();
    if(c==STEMc||c==ASFc) return c==STEMc? mkStem(subst_rec(x.ch[0],idxN,k)) : mkAsf(subst_rec(x.ch[0],idxN,k));
    if(c==FORKc||c==FUNTYc) return c==FORKc? mkFork(subst_rec(x.ch[0],idxN,k),subst_rec(x.ch[1],idxN,k)) : mkFunty(subst_rec(x.ch[0],idxN,k),subst_rec(x.ch[1],idxN,k));
    if(c==QUANTc) return mkQuant(subst_rec(x.ch[0],idxN,k+1));
    assert(false);
}
int substty(int t,int N){return subst_rec(t,N,0);}

int Nsz; int NV;
// generate all types by size up to Nsz with vars 0..NV-1
map<int, vector<int>> bySize;
void genTypes(){
    LEAF=mkLeaf(); VAR0=mkV(0);
    bySize[1].push_back(LEAF); for(int i=0;i<NV;i++) bySize[1].push_back(mkV(i));
    for(int s=2;s<=Nsz;s++){
        vector<int> cur;
        auto add=[&](int id){ static set<int> seen; (void)seen; cur.push_back(id); };
        // unary
        for(int a=1;a<=s-1;a++) for(int x: bySize[a]){
            add(mkStem(x)); add(mkAsf(x)); add(mkQuant(x));
