    for(int s=2;s<=Nsz;s++){
        vector<int> cur;
        auto add=[&](int id){ static set<int> seen; (void)seen; cur.push_back(id); };
        // unary
        for(int a=1;a<=s-1;a++) for(int x: bySize[a]){
            add(mkStem(x)); add(mkAsf(x)); add(mkQuant(x));
        }
        // binary
        for(int a=1;a<=s-1;a++) for(int x: bySize[a]) { int b=s-1-a; if(b<1) continue; for(int y: bySize[b]) { add(mkFork(x,y)); add(mkFunty(x,y)); } }
        sort(cur.begin(),cur.end()); cur.erase(unique(cur.begin(),cur.end()),cur.end());
