import sys
sys.path.insert(0,'/tmp/explore')
from tps import *
from gen import univ

N=int(sys.argv[1]); NV=int(sys.argv[2]) if len(sys.argv)>2 else 1
U,Uby=univ(N,NV)
Ul=sorted(U)
idx={t:i for i,t in enumerate(Ul)}
n=len(Ul)
R=[set() for _ in range(n)]
def I(t): return idx.get(t,None)
def addn(new,a,b):
    ia,ib=I(a),I(b)
    if ia is not None and ib is not None and ib not in R[ia] and ib not in new[ia]:
        new[ia].add(ib); return 1
    return 0
for t,i in idx.items(): R[i].add(i)
def subq(a,b):
    ia,ib=I(a),I(b)
    return ia is not None and ib is not None and ib in R[ia]

stems=[(i,t[1]) for i,t in enumerate(Ul) if t[0]=='Stem']
asfs=[(i,t[1]) for i,t in enumerate(Ul) if t[0]=='Asf']
quants=[(i,t[1]) for i,t in enumerate(Ul) if t[0]=='Quant']
funtys=[(i,t[1],t[2]) for i,t in enumerate(Ul) if t[0]=='Funty']
forks=[(i,t[1],t[2]) for i,t in enumerate(Ul) if t[0]=='Fork']

def round_():
    new=[set() for _ in range(n)]
    c=0
    # stem
    for i,x in stems:
        for j,y in stems:
            if subq(x,y): c+=addn(new,Ul[i],Ul[j])
    for i,x in asfs:
        for j,y in asfs:
            if subq(x,y): c+=addn(new,Ul[i],Ul[j])
    for i,x in quants:
        for j,y in quants:
            if subq(x,y): c+=addn(new,Ul[i],Ul[j])
    for i,x,y in funtys:
        for j,a,w in funtys:
            if subq(a,x) and subq(y,w): c+=addn(new,Ul[i],Ul[j])
    for i,x,y in forks:
        for j,y2,z2 in forks:
            if subq(x,y2) and subq(y,z2): c+=addn(new,Ul[i],Ul[j])
    # concrete schemas
    for a in Ul:
        k=a[0]
        if k=='Stem': c+=addn(new,Quant(Stem(a[1])),Stem(Quant(a[1])))
        if k=='Fork': c+=addn(new,Quant(a),Fork(Quant(a[1]),Quant(a[2])))
        if k=='Asf': c+=addn(new,Quant(a),Asf(Quant(a[1])))
        if k=='Funty': c+=addn(new,Quant(a),Funty(Quant(a[1]),Quant(a[2])))
        for u in Ul: c+=addn(new,Quant(a),subst(a,u))
        c+=addn(new,a,Quant(lift(1,a)))
        c+=addn(new,a,Asf(a))
        if k=='Funty': c+=addn(new,Asf(a),a)
        c+=addn(new,LEAF,Funty(a,Stem(a)))
    for x in Ul:
        for a in Ul:
            c+=addn(new,Stem(x),Funty(a,Fork(x,a)))
            c+=addn(new,Fork(LEAF,x),Funty(a,x))
    for i,s in enumerate(Ul):
        if s[0]=='Fork':
            x,y=s[1],s[2]
            # fork_stem: x=Stem h, h=Funty X (Funty Y Z), y=Funty X Y
            if x[0]=='Stem' and x[1][0]=='Funty' and x[1][2][0]=='Funty' and y[0]=='Funty':
                X=x[1][1]; Y=x[1][2][1]; Z=x[1][2][2]
                if y==Funty(X,Y): c+=addn(new,s,Funty(X,Z))
            # fork_fork_*
            if x[0]=='Fork':
                u,v=x[1],x[2]
                c+=addn(new,s,Funty(LEAF,u))   # fork_fork_leaf
                if v[0]=='Funty':
                    c+=addn(new,s,Funty(Stem(v[1]),v[2]))  # fork_fork_stem
                if y[0]=='Funty' and y[2][0]=='Funty':
                    c+=addn(new,s,Funty(Fork(y[1],y[2][1]),y[2][2])) # fork_fork_fork
    for i in range(n):
        if new[i]:
            c+=0; R[i].update(new[i])
    return c

r=0
while True:
    r+=1; c=round_(); print("round",r,"new",c,flush=True)
    if c==0 or r>10: break
# trans closure
reach=[set(rr) for rr in R]
for k in range(n):
    rk=reach[k]
    for i in range(n):
        if k in reach[i]: reach[i]|=rk
R=reach
def sub(a,b):
    ia,ib=I(a),I(b)
    return ia is not None and ib is not None and ib in R[ia]

print("check L1:")
v=[(a,b) for a in Ul for b in Ul if sub(LEAF,Funty(a,b)) and not sub(Stem(a),b)]
print("L1 violations",len(v))
for a,b in v[:15]: print(a,"|",b)
print("check L1 restricted b Funty:")
v2=[(a,b) for a in Ul for b in Ul if b[0]=='Funty' and sub(LEAF,Funty(a,b)) and not sub(Stem(a),b)]
print("L1fun violations",len(v2))
for a,b in v2[:10]: print(a,"|",b)
print("check K:")
vk=[]
for u2 in Ul:
    if not sub(LEAF,u2): continue
    for u1 in Ul:
        for u in Ul:
            for ty in Ul:
                T=Funty(u2,Funty(u1,Funty(u,ty)))
                if T in idx and sub(LEAF,T) and not sub(u1,ty):
                    vk.append((u2,u1,u,ty))
print("K violations",len(vk))
for t in vk[:10]: print(t)
