from itertools import product
from functools import lru_cache

# type constructors as tuples
V=('V',0); W=('V',1); L=('L',)
def Q(t): return ('Q',t)
def F(a,b): return ('F',a,b)
def St(t): return ('S',t)
def Fo(a,b): return ('K',a,b)
def As(t): return ('A',t)

# size
def size(t):
    k=t[0]
    if k=='V': return 1
    if k=='L': return 1
    if k in 'QSA': return 1+size(t[1])
    return 1+size(t[1])+size(t[2])

def subst(t,N,k=0):
    kk=t[0]
    if kk=='V':
        i=t[1]
        if i<k: return ('V',i)
        if i==k: return lift(N,k)
        return ('V',i-1)
    if kk=='Q': return ('Q',subst(t[1],N,k+1))
