from tps import *

def univ(N, nvars=1):
    # all types with size exactly or <= N
    bysize={0:set(),1:set()}
    bysize[1].add(LEAF)
    for i in range(nvars): bysize[1].add(Var(i))
    for s in range(2,N+1):
        cur=set()
        for a in range(1,s):
            for x in bysize[a]:
                for y in bysize[s-1-a]:
                    cur.add(Fork(x,y)); cur.add(Funty(x,y))
                cur.add(Stem(x)); cur.add(Asf(x)); cur.add(Quant(x))
        bysize[s]=cur
    U=set()
    for s in range(1,N+1): U|=bysize[s]
    return U,bysize

for N in [3,4,5,6]:
    U,_=univ(N,1)
    print(N,len(U))
from itertools import product

# type representation tuples: ('Var',n), ('Leaf',), ('Stem',x), ('Fork',x,y), ('Funty',x,y), ('Asf',x), ('Quant',x)
LEAF=('Leaf',)
def Var(n): return ('Var',n)
def Stem(x): return ('Stem',x)
def Fork(x,y): return ('Fork',x,y)
def Funty(x,y): return ('Funty',x,y)
def Asf(x): return ('Asf',x)
def Quant(x): return ('Quant',x)

def size(t):
    k=t[0]
    if k in ('Leaf',): return 1
    if k in ('Var',): return 1
    return 1+sum(size(x) for x in t[1:])

def lift_rec(t,k,n):
    k0=t[0]
    if k0=='Var':
        i=t[1]
        return Var(n+i if k<=i else i)
    if k0=='Leaf': return LEAF
    if k0 in ('Stem','Asf'): return (k0, lift_rec(t[1],k,n))
    if k0 in ('Fork','Funty'): return (k0, lift_rec(t[1],k,n), lift_rec(t[2],k,n))
    if k0=='Quant': return Quant(lift_rec(t[1],k+1,n))
    raise Exception(t)
def lift(n,t): return lift_rec(t,0,n)

def test(n,m): return True if n<=m else False  # {n<=m}
def le_lt(n,m): return n<m
def compare(n,m): return -1 if n<m else (0 if n==m else 1)
def relocate(i,k,n): return n+i if k<=i else i
def insert_Var(N,i,k):
    c=compare(k,i)
    if c<0: return Var(i-1)
    elif c==0: return lift(k,N)
    else: return Var(i)
def subst_rec(t,N,k):
    k0=t[0]
    if k0=='Var': return insert_Var(N,t[1],k)
    if k0=='Leaf': return LEAF
    if k0 in ('Stem','Asf'): return (k0, subst_rec(t[1],N,k))
    if k0 in ('Fork','Funty'): return (k0, subst_rec(t[1],N,k), subst_rec(t[2],N,k))
    if k0=='Quant': return Quant(subst_rec(t[1],N,k+1))
    raise Exception(t)
def subst(t,N): return subst_rec(t,N,0)

def quant(n,ty):
    for _ in range(n): ty=Quant(ty)
    return ty
def quantf(n,ty):
    for _ in range(n): ty=Asf(ty)
    return ty
# omega types
K = Fork(LEAF,LEAF)   # not used here? K=Node@Node type? careful: K defined as term; type program_type(K)=Stem Leaf maybe
# Let's compute program_type for omega21, omega22? Too complex; skip for now; sub_recursion/sub_tree require these.
