    if kk=='F': return ('F',lift(t[1],n,k),lift(t[2],n,k))
    if kk=='S': return ('S',lift(t[1],n,k))
    if kk=='K': return ('K',lift(t[1],n,k),lift(t[2],n,k))
    if kk=='A': return ('A',lift(t[1],n,k))
