import sys
V=('V',0); W=('V',1); L=('L',)
def Q(t): return ('Q',t)
def F(a,b): return ('F',a,b)
def St(t): return ('S',t)
def Fo(a,b): return ('K',a,b)
def As(t): return ('A',t)
def size(t):
    k=t[0]
    if k=='V' or k=='L': return 1
    if k in ('Q','S','A'): return 1+size(t[1])
    return 1+size(t[1])+size(t[2])
def lift(t,n,k=0):
    kk=t[0]
    if kk=='V':
        i=t[1]; return ('V', i+n if k<=i else i)
    if kk=='Q': return ('Q',lift(t[1],n,k+1))
    if kk=='F': return ('F',lift(t[1],n,k),lift(t[2],n,k))
    if kk=='S': return ('S',lift(t[1],n,k))
    if kk=='K': return ('K',lift(t[1],n,k),lift(t[2],n,k))
