        at(u,('Q',lift(u,1)))                      # sub_lift
        at(u,('A',u))                              # sub_to_asf
        at(('A',('K',u,('V',0))),('K',u,('V',0)))  # not used
        at(('Q',('S',u)),('S',('Q',u)))            # sub_quant_stem
        at(('Q',('A',u)),('A',('Q',u)))            # sub_quant_asf
        for v in types:
            at(('Q',('K',u,v)),('K',('Q',u),('Q',v)))  # sub_dist
            at(('Q',('F',u,v)),('F',('Q',u),('Q',v)))  # sub_quant_fork
            at(('S',u),('K',v,('F',u,v)))              # sub_stem_fun
            at(('F',L,u),('K',v,u))                    # sub_fork_leaf
            at(('A',('K',u,v)),('K',u,v))              # sub_from_asf
            for w in types:
                at(('F',('S',('K',u,('K',v,w)))),('K',u,v)),('K',u,w)) # sub_fork_stem
                at(('F',('F',u,v),w),('K',L,u))        # sub_fork_fork_leaf
                at(('F',('F',u,('K',v,w))),('K',('S',v),w)) # sub_fork_fork_stem (vty1=v,vty2=w? careful)
                at(('F',('F',u,v),('K',w,('K',v,u))),('K',('F',v,u),v)) # placeholder
                # sub_bffs
                at(('F',('S',bffs_aug(u)),('A',v)),('A',('F',('S',u),v)))
                # sub_bfff
                at(('F',('F',u,('A',v))),bfff_aug(w)),('A',('F',('F',u,v),w)))
    # sub_fork_fork_stem exact: Fork (Fork uty (Funty vty1 vty2)) wty <: Funty (Stem vty1) vty2
    for u in types:
        for v1 in types:
            for v2 in types:
                at(('F',('F',u,('K',v1,v2))),('K',('S',v1),v2))
    # sub_fork_fork_fork exact: Fork (Fork uty vty) (Funty w1 (Funty w2 w3)) <: Funty (Fork w1 w2) w3
    for u in types:
        for v in types:
            for w1 in types:
                for w2 in types:
                    for w3 in types:
                        at(('F',('F',u,v),('K',w1,('K',w2,w3)))),('K',('F',w1,w2),w3)))
    # sub_inst
    for ty in types:
        for u in types:
            at(('Q',ty),subst(ty,u))
    # sub_recursion
    for k in range(kmax+1):
        for u in types:
            for v in types:
                q=quant(k,('K',u,v))
                at(omega2_ty,('K',omega2_ty,('K',('K',q,q),q))))
    # sub_tree
    for ty in types:
        if covariant(ty):
            src=('F',('F',subst(ty,L),quant(1,('K',('V',0),subst(lift_rec(ty,1,1),('S',('V',0))))))),
                     quant(2,('K',('V',1),('K',('V',0),subst(lift_rec(ty,1,2),('F',('V',1),('V',0)))))))
            for uty in types:
                at(src,('K',uty,subst(ty,uty)))
    print("atomic",sum(bin(x).count('1') for x in reach),"time",round(time.time()-t0,2),flush=True)
    # structural closure + trans
    it=0
    while True:
        it+=1; old=sum(bin(x).count('1') for x in reach)
        # transitive
        for k in range(n):
            rk=reach[k]; bit=1<<k
            for i in range(n):
                if reach[i]&bit: reach[i]|=rk
        # collect pairs by source structure
        pairs=[(i,j) for i in range(n) for j in bits(reach[i])]
        for i,j in pairs:
            a,b=types[i],types[j]
            add(('S',a),('S',b)); add(('A',a),('A',b)); add(('Q',a),('Q',b))
        # funty/fork structural: iterate pairs of reach pairs; O(E^2)
        for (i,j) in pairs:
            a,b=types[i],types[j]
            for (c,d) in pairs:
                e,f=types[c],types[d]
                if sz(('K',a,e))<=maxsize and sz(('K',b,f))<=maxsize:
                    add(('K',a,e),('K',b,f))
                if sz(('F',a,e))<=maxsize and sz(('F',b,f))<=maxsize:
                    add(('F',a,e),('F',b,f))
        new=sum(bin(x).count('1') for x in reach)
        print("iter",it,"pairs",new,"time",round(time.time()-t0,2),flush=True)
        if new==old or it>20: break
    return types,reach,idx

if __name__=='__main__':
    m=int(sys.argv[1]); mv=int(sys.argv[2]); km=int(sys.argv[3]) if len(sys.argv)>3 else 2
    types,reach,idx=run(m,mv,km)
    import pickle
    pickle.dump((types,reach,idx),open('/tmp/agentA_model/reach_fixed.pkl','wb'))
    print("saved")
