deque<pair<int,int>> work;
bool add(int a,int b){ if(a<0||b<0||a>=N||b>=N) return false; if(getbit(reach[a],b)) return false; setbit(reach[a],b); setbit(pred[b],a); pairs.push_back({a,b}); work.push_back({a,b}); return true; }
