    auto addobj=[&](char k,int a,int b,int s){ if(s>maxs) return; Type t{k,a,b}; int id=T.size(); T.push_back(t); ID[enc(k,a,b)]=id; by[s].push_back(id); };
    addobj('L',-1,-1,1); addobj('V',0,-1,1); if(vars>1) addobj('V',1,-1,1);
    for(int s=2;s<=maxs;s++){
        vector<int> cand;
        for(int t: by[s-1]){ for(char k: {'Q','S','A'}) cand.push_back(-1); }
        // build via lookups after adding? Need sizes and unique. Do explicit loops.
        vector<Type> newts;
        for(int t: by[s-1]){ for(char k: {'Q','S','A'}){ Type nt{k,t,-1}; newts.push_back(nt);} }
        for(int i=1;i<=s-2;i++){ int j=s-1-i; for(int a: by[i]) for(int b: by[j]){ newts.push_back(Type{'F',a,b}); newts.push_back(Type{'K',a,b}); } }
        // dedup
        for(auto &nt: newts){ unsigned long long e=enc(nt.k,nt.a,nt.b); if(ID.count(e)) continue; int id=T.size(); T.push_back(nt); ID[e]=id; by[s].push_back(id); }
