        (void)src2;
    }
    for(int u=0;u<N;u++) for(int v1=0;v1<N;v1++) for(int v2=0;v2<N;v2++) for(int w=0;w<N;w++){
        int src=at('K',at('K',u,at('F',v1,v2)),w); int tgt=at('F',at('S',v1,-1),v2); addt(src,tgt);
    }
    for(int u=0;u<N;u++) for(int v=0;v<N;v++) for(int w1=0;w1<N;w1++) for(int w2=0;w2<N;w2++) for(int w3=0;w3<N;w3++){
        int src=at('K',at('K',u,v),at('F',w1,at('F',w2,w3))); int tgt=at('F',at('K',w1,w2),w3); addt(src,tgt);
    }
    cerr<<"atomic pairs "<<pairs.size()<<"\n";
    long long steps=0;
    while(!work.empty()){
