import sys,time
L=('L',)
Kt=('A',('N',),('N',))
def S1(x): return ('A',('N',),('A',('N',),x))
I=('A',S1(Kt),Kt)
def occurs(x,M):
    if M[0]=='R': return x==M[1]
    if M[0]=='N': return False
    return occurs(x,M[1]) or occurs(x,M[2])
def star(x,M):
    if M[0]=='R': return I if x==M[1] else ('A',Kt,('R',M[1]))
    if M[0]=='N': return ('A',Kt,('N',))
    if occurs(x,M): return ('A',S1(star(x,M[1])),star(x,M[2]))
    return ('A',Kt,M)
def wait2(M,N,x):
    a=('A',Kt,M); b=S1(a); c=('A',Kt,N); d=('A',b,c); e=S1(d)
    f=('A',Kt,x); g=('A',e,f); h=S1(g); return ('A',h,I)
def program_type(p):
    if p[0]=='N': return L
    if p[0]=='R': return ('K',L,L)
    m,n=p[1],p[2]; t1=program_type(m)
    if t1==L: return ('S',program_type(n))
    if t1[0]=='S': return ('F',t1[1],program_type(n))
    return ('K',L,L)
omega21=('A',('A',('N',),('N',)),('A',('N',),('A',('N',),I)))
omega22=star('w',star('f',wait2(('R','w'),('R','w'),('R','f'))))
omega21_ty=program_type(omega21); omega22_ty=program_type(omega22)
omega2_ty=('F',('S',omega21_ty),omega22_ty)
eval_ty=('Q',('K',('V',0),('A',('V',0))))
eager_ty=('Q',('Q',('K',('K',('V',0),('V',1)),('K',('V',0),('V',1)))))
def bfff_aug(u): return ('F',('S',('F',L,eval_ty)),('A',u))
def bffs_aug(u): return ('F',('S',('F',L,eager_ty)),bfff_aug(u))

def sz(t):
    c=t[0]
    if c in 'VL': return 1
    if c in 'QSA': return 1+sz(t[1])
    return 1+sz(t[1])+sz(t[2])
def subst_rec(t,N,k):
    c=t[0]
    if c=='V':
        i=t[1]
        if i<k: return t
        if i==k: return lift_rec(N,0,k)
        return ('V',i-1)
    if c=='L': return t
    if c=='Q': return ('Q',subst_rec(t[1],N,k+1))
    if c=='S': return ('S',subst_rec(t[1],N,k))
    if c=='A': return ('A',subst_rec(t[1],N,k))
    return (c,subst_rec(t[1],N,k),subst_rec(t[2],N,k))
def subst(t,N): return subst_rec(t,N,0)
def lift_rec(t,k,n):
    c=t[0]
    if c=='V': return ('V',n+t[1] if k<=t[1] else t[1])
    if c=='L': return t
    if c=='Q': return ('Q',lift_rec(t[1],k+1,n))
    if c=='S': return ('S',lift_rec(t[1],k,n))
    if c=='A': return ('A',lift_rec(t[1],k,n))
    return (c,lift_rec(t[1],k,n),lift_rec(t[2],k,n))
def lift(t,n=1): return lift_rec(t,0,n)
def quant(n,t):
    for _ in range(n): t=('Q',t)
    return t
def gen_types(maxsize,maxvar):
    by={i:[] for i in range(1,maxsize+1)}
    by[1]=[L]+[('V',i) for i in range(maxvar)]
    for s in range(2,maxsize+1):
        cur=[]
        for t in by[s-1]:
            for c in 'QSA': cur.append((c,t))
        for i in range(1,s-1):
            j=s-1-i
            for a in by[i]:
                for b in by[j]:
                    cur.append(('F',a,b)); cur.append(('K',a,b))
        seen=set(); out=[]
        for t in cur:
            if t not in seen: seen.add(t); out.append(t)
        by[s]=out
    types=[]
    for s in range(1,maxsize+1): types+=by[s]
    return types
def bits(x):
    while x:
        b=x&-x; yield b.bit_length()-1; x-=b
def variant(pos,k,ty):
    c=ty[0]
    if c=='V': return pos if k==ty[1] else True
    if c=='Q': return variant(pos,k+1,ty[1])
    if c=='K': return variant(not pos,k,ty[1]) and variant(pos,k,ty[2])
    if c=='L': return True
    if c=='S' or c=='A': return variant(pos,k,ty[1])
    return variant(pos,k,ty[1]) and variant(pos,k,ty[2])
def covariant(t): return variant(True,0,t)

def run(maxsize=4,maxvar=3,kmax=2):
    t0=time.time()
    types=gen_types(maxsize,maxvar); idx={t:i for i,t in enumerate(types)}; n=len(types)
    print("types",n,"omega sizes",sz(omega21_ty),sz(omega22_ty),sz(omega2_ty),flush=True)
    reach=[0]*n
    def add(a,b):
        ia=idx.get(a); ib=idx.get(b)
        if ia is None or ib is None: return False
        if reach[ia]>>ib &1: return False
        reach[ia]|=1<<ib; return True
    def at(a,b):
        if a in idx and b in idx: add(a,b)
    # reflexive + atomic rules (subtypes.v), generated from existing sources
    def Q(t): return ('Q',t)
    def S(t): return ('S',t)
    def A(t): return ('A',t)
    def F(a,b): return ('F',a,b)
    def K(a,b): return ('K',a,b)
    for t in types:
        at(t,t)                                 # sub_zero
        at(t,Q(lift(t,1)))                      # sub_lift
        at(t,A(t))                              # sub_to_asf
        # source-shape matched atomic rules
        if t[0]=='S':
            u=t[1]
            at(t, K(('V',0), F(u,('V',0))))     # placeholder; sub_stem_fun handled below per v
        if t[0]=='F':
            l,r=t[1],t[2]
            if l==L:
                for v in types: at(t,K(v,r))    # sub_fork_leaf
            if l[0]=='S' and l[1][0]=='K':
                _,u,vw=l; uu=u
                if vw[0]=='K':
                    v,w=vw[1],vw[2]
                    at(t,K(uu,v))           # sub_fork_stem
            if l[0]=='F':
                u,v=l[1],l[2]
                at(t,K(L,u))                # sub_fork_fork_leaf
                if v[0]=='K':
                    v1,v2=v[1],v[2]
                    at(t,K(S(v1),v2))       # sub_fork_fork_stem
                if r[0]=='K' and r[2][0]=='K':
                    w1,w2,w3=r[1],r[2][1],r[2][2]
                    at(t,K(F(w1,w2),w3))    # sub_fork_fork_fork
            # sub_bffs: t = F (S (bffs_aug u)) (A v)
            if l[0]=='S' and l[1][0]=='F':
                au=l[1]
                # bffs_aug u = F (S (F L eager_ty)) (bfff_aug u)
                if au[1][0]=='S' and au[1][1]==F(L,eager_ty) and r[0]=='A':
                    bfa=au[2]
                    if bfa[0]=='F' and bfa[1][0]=='S' and bfa[1][1]==F(L,eval_ty) and bfa[2][0]=='A':
                        u=bfa[2][1]; v=r[1]
                        if v[0]=='F' and v[1][0]=='S':
                            at(t,A(F(S(u),v[2])))   # sub_bffs target A(F(S u) vty)
            # sub_bfff: t = F (F u (A v)) (bfff_aug w)
            if l[0]=='F' and l[2][0]=='A' and r[0]=='F':
                u=l[1]; v=l[2][1]
                bfa=r
                if bfa[1][0]=='S' and bfa[1][1]==F(L,eval_ty) and bfa[2][0]=='A':
                    w=bfa[2][1]
                    at(t,A(F(F(u,v),w)))        # sub_bfff
        if t[0]=='Q':
            ty=t[1]
            for u in types: at(t,subst(ty,u))   # sub_inst
            if ty[0]=='S':
                at(t,S(Q(ty[1])))               # sub_quant_stem
            if ty[0]=='A':
                at(t,A(Q(ty[1])))               # sub_quant_asf
            if ty[0]=='F':
                at(t,F(Q(ty[1]),Q(ty[2])))      # sub_quant_fork
            if ty[0]=='K':
                at(t,K(Q(ty[1]),Q(ty[2])))      # sub_dist
        if t[0]=='A' and t[1][0]=='K':
            at(t,t[1])                          # sub_from_asf
        # sub_stem_fun: Stem u <: Funty v (Fork u v)
        if t[0]=='S':
            u=t[1]
            for v in types: at(t,K(v,F(u,v)))
    # sub_recursion
    for k in range(kmax+1):
        for u in types:
            for v in types:
                q=quant(k,K(u,v))
                at(omega2_ty, K(omega2_ty, K(K(q,q),q)))
    # sub_tree
    for ty in types:
        if covariant(ty):
            A0 = subst(ty,L)
            B0 = quant(1, K(('V',0), subst(lift_rec(ty,1,1), S(('V',0)))))
            C0 = quant(2, K(('V',1), K(('V',0), subst(lift_rec(ty,1,2), F(('V',1),('V',0))))))
            src = F(F(A0,B0),C0)
            for uty in types:
                at(src, K(uty,subst(ty,uty)))
    print("atomic",sum(bin(x).count('1') for x in reach),"time",round(time.time()-t0,2),flush=True)
    # structural closure + trans
    it=0
    while True:
        it+=1; old=sum(bin(x).count('1') for x in reach)
        # transitive
        for k in range(n):
            rk=reach[k]; bit=1<<k
            for i in range(n):
                if reach[i]&bit: reach[i]|=rk
        # collect pairs by source structure
        pairs=[(i,j) for i in range(n) for j in bits(reach[i])]
        for i,j in pairs:
            a,b=types[i],types[j]
            add(('S',a),('S',b)); add(('A',a),('A',b)); add(('Q',a),('Q',b))
        # funty/fork structural: iterate pairs of reach pairs; O(E^2)
        for (i,j) in pairs:
            a,b=types[i],types[j]
            for (c,d) in pairs:
                e,f=types[c],types[d]
                if sz(('K',a,e))<=maxsize and sz(('K',b,f))<=maxsize:
                    add(('K',a,e),('K',b,f))
                if sz(('F',a,e))<=maxsize and sz(('F',b,f))<=maxsize:
                    add(('F',a,e),('F',b,f))
        new=sum(bin(x).count('1') for x in reach)
        print("iter",it,"pairs",new,"time",round(time.time()-t0,2),flush=True)
        if new==old or it>20: break
    return types,reach,idx

if __name__=='__main__':
    m=int(sys.argv[1]); mv=int(sys.argv[2]); km=int(sys.argv[3]) if len(sys.argv)>3 else 2
    types,reach,idx=run(m,mv,km)
    import pickle
    pickle.dump((types,reach,idx),open('/tmp/agentA_model/reach_fixed.pkl','wb'))
    print("saved")

