#include <bits/stdc++.h>
using namespace std;
using BS = vector<uint64_t>;
int N;
vector<BS> reach, pred;
vector<pair<int,int>> pairs;
vector<int> tsz;
vector<vector<vector<int>>> buckets;
inline bool getbit(const BS&b,int i){return (b[i>>6]>>(i&63))&1ULL;}
inline void setbit(BS&b,int i){b[i>>6]|=1ULL<<(i&63);}
struct Type { char k; int a,b; };
vector<Type> T;
map<unsigned long long,int> ID;
unsigned long long enc(char k,int a,int b){ return (unsigned long long)(unsigned char)k | ((unsigned long long)(a+1)<<8) | ((unsigned long long)(b+1)<<24); }
int lookup(char k,int a=-1,int b=-1){ auto it=ID.find(enc(k,a,b)); return it==ID.end()?-1:it->second; }
int vars=2, maxs=6;
int sz(const Type&t){ if(t.k=='V'||t.k=='L') return 1; if(t.k=='Q'||t.k=='S'||t.k=='A') return 1+ (t.a>=0?sz(T[t.a]):0); return 1+(t.a>=0?sz(T[t.a]):0)+(t.b>=0?sz(T[t.b]):0); }
void gen(){
    vector<vector<int>> by(maxs+1);
    // temporary objects built directly with ids; first create size 1
    auto addobj=[&](char k,int a,int b,int s){ if(s>maxs) return; Type t{k,a,b}; int id=T.size(); T.push_back(t); ID[enc(k,a,b)]=id; by[s].push_back(id); };
    addobj('L',-1,-1,1); for(int v=0; v<vars; v++) addobj('V',v,-1,1);
    for(int s=2;s<=maxs;s++){
        vector<int> cand;
        for(int t: by[s-1]){ for(char k: {'Q','S','A'}) cand.push_back(-1); }
        // build via lookups after adding? Need sizes and unique. Do explicit loops.
        vector<Type> newts;
        for(int t: by[s-1]){ for(char k: {'Q','S','A'}){ Type nt{k,t,-1}; newts.push_back(nt);} }
        for(int i=1;i<=s-2;i++){ int j=s-1-i; for(int a: by[i]) for(int b: by[j]){ newts.push_back(Type{'F',a,b}); newts.push_back(Type{'K',a,b}); } }
        // dedup
        for(auto &nt: newts){ unsigned long long e=enc(nt.k,nt.a,nt.b); if(ID.count(e)) continue; int id=T.size(); T.push_back(nt); ID[e]=id; by[s].push_back(id); }
    }
    N=T.size();
}
void addpair(int a,int b);
deque<pair<int,int>> work;
bool add(int a,int b){ if(a<0||b<0||a>=N||b>=N) return false; if(getbit(reach[a],b)) return false; setbit(reach[a],b); setbit(pred[b],a); int pi=pairs.size(); pairs.push_back({a,b}); buckets[tsz[a]][tsz[b]].push_back(pi); work.push_back({a,b}); return true; }
void propagate(int a,int b){
    // transitivity seminaive: for all x with x->a, add x->b; for all d with b->d, add a->d
    // copy preds[a] to avoid invalidation
    for(int wi=0; wi< (int)pred[a].size(); wi++){ uint64_t w=pred[a][wi]; while(w){ int x=__builtin_ctzll(w)+wi*64; w&=w-1; add(x,b);} }
    for(int wi=0; wi< (int)reach[b].size(); wi++){ uint64_t w=reach[b][wi]; while(w){ int d=__builtin_ctzll(w)+wi*64; w&=w-1; add(a,d);} }
    // unary
    int sa=lookup('S',a), sb=lookup('S',b); if(sa>=0&&sb>=0) add(sa,sb);
    int aa=lookup('A',a), ab=lookup('A',b); if(aa>=0&&ab>=0) add(aa,ab);
    int qa=lookup('Q',a), qb=lookup('Q',b); if(qa>=0&&qb>=0) add(qa,qb);
}
void combine(int a,int b){
    // combine with all existing pairs; use sizes and lookup, both orientations
    for(auto [c,d]: vector<pair<int,int>>(pairs)){ // copy expensive; use index snapshot instead
        int kac=lookup('K',a,c), kbd=lookup('K',b,d); if(kac>=0&&kbd>=0) add(kac,kbd);
        int kca=lookup('K',c,a), kdb=lookup('K',d,b); if(kca>=0&&kdb>=0) add(kca,kdb);
        int fac=lookup('F',a,c), fbd=lookup('F',b,d); if(fac>=0&&fbd>=0) add(fac,fbd);
        int fca=lookup('F',c,a), fdb=lookup('F',d,b); if(fca>=0&&fdb>=0) add(fca,fdb);
    }
}
int main(int argc,char**argv){ maxs= argc>1?atoi(argv[1]):6; vars=argc>2?atoi(argv[2]):1; gen(); cerr<<"N="<<N<<"\n";
    reach.assign(N,BS((N+63)/64)); pred.assign(N,BS((N+63)/64)); tsz.assign(N,0); for(int i=0;i<N;i++) tsz[i]=sz(T[i]); buckets.assign(maxs+1, vector<vector<int>>(maxs+1));
    auto at=[&](char k,int a,int b){ int x=lookup(k,a,b); return x; };
    auto addt=[&](int x,int y){ if(x>=0&&y>=0) add(x,y); };
    // atomic
    for(int i=0;i<N;i++){ addt(i,i); int a=at('A',i,-1); if(a>=0) addt(i,a); }
    for(int i=0;i<N;i++){
        // leaf_fun: L <: F i (S i)
        int si=at('S',i,-1); int f=at('F',i,si); addt(at('L',-1,-1), f);
        // stem_fun: S i <: F j (K i j)
        for(int j=0;j<N;j++){ int k=at('K',i,j); int f2=at('F',j,k); addt(at('S',i,-1),f2); }
        // fork_leaf: K L i <: F j i
        int kl=at('K',at('L',-1,-1),i); if(kl>=0) for(int j=0;j<N;j++){ int f3=at('F',j,i); addt(kl,f3); }
        // quant_stem Q(S i) <: S(Q i)
        int qs=at('Q',at('S',i,-1),-1), sq=at('S',at('Q',i,-1),-1); addt(qs,sq);
        // quant_asf Q(A i) <: A(Q i)
        int qa=at('Q',at('A',i,-1),-1), aq=at('A',at('Q',i,-1),-1); addt(qa,aq);
        // lift i <: Q(lift i)
        // implement lift_rec on T for k=0,n=1 producing id
        function<int(int,int,int)> liftid = [&](int id,int k,int n)->int{
            Type t=T[id];
            if(t.k=='V'){ int idx=t.a; return at('V', (idx>=k?idx+n:idx),-1); }
            if(t.k=='L') return id;
            if(t.k=='Q'){ int b=liftid(t.a,k+1,n); return at('Q',b,-1); }

        if(t.k=='Q'){ int b=liftid(t.a,k+1,n); return at('Q',b,-1); }
        if(t.k=='S'||t.k=='A'){ int b=liftid(t.a,k,n); return at(t.k,b,-1); }
        int x=liftid(t.a,k,n), y=liftid(t.b,k,n); return at(t.k,x,y);
