    if c=='V': return ('V',n+t[1] if k<=t[1] else t[1])
    if c=='L': return t
    if c=='Q': return ('Q',lift_rec(t[1],k+1,n))
    if c=='S': return ('S',lift_rec(t[1],k,n))
    if c=='A': return ('A',lift_rec(t[1],k,n))
    return (c,lift_rec(t[1],k,n),lift_rec(t[2],k,n))
def lift(t,n=1): return lift_rec(t,0,n)
def quant(n,t):
