import itertools, sys

# Type representation as tuples
VARS = [('Var',0),('Var',1),('Var',2)]
LEAF = ('Leaf',)

def unary(c, t): return (c,t)
def binary(c,a,b): return (c,a,b)

def size(t):
    if t[0] in ('Var','Leaf'): return 1
    if t[0] in ('Stem','Quant','Asf'): return 1+size(t[1])
    if t[0] in ('Fork','Funty'): return 1+size(t[1])+size(t[2])

# generate all types up to size N over VARS and Leaf
def gen(N):
    # by size
    levels = {1: set(VARS+[LEAF])}
    allset = set(levels[1])
    for s in range(2,N+1):
        cur=set()
        # unary
        for u in ('Stem','Quant','Asf'):
            for t in allset:
                if size(t)+1==s: cur.add((u,t))
        # binary
        for c in ('Fork','Funty'):
            for a in allset:
                for b in allset:
                    if size(a)+size(b)+1==s: cur.add((c,a,b))
        levels[s]=cur
        allset |= cur
    return allset, levels

