    c=t[0]
    if c=='Var': return insert_Var(N,t[1],k)
    if c=='Leaf': return LEAF
    if c=='Quant': return ('Quant', subst_rec(t[1],N,k+1))
    if c in ('Stem','Asf'): return (c, subst_rec(t[1],N,k))
    if c in ('Fork','Funty'): return (c, subst_rec(t[1],N,k), subst_rec(t[2],N,k))
