            bytgt.setdefault(b,[]).append(a)
        for (a,b) in list(R):
            for c in bytgt.get(a,[]):
                if (c,b) not in R:
                    newpairs.append((c,b))
        for p in newpairs:
            if add(*p): changed=True
        # structural
        for a,b in list(R):
