        # funty contra/cov
        for (u2,u1) in list(R):  # uty2 <: uty1
            for (v1,v2) in list(R):
                if add(('Funty',u1,v1),('Funty',u2,v2)): changed=True
        # atomic unary/dist
        for uty in U:
            # quant_stem etc
            if add(('Quant',('Stem',uty)),('Stem',('Quant',uty))): changed=True
            if add(('Quant',('Asf',uty)),('Asf',('Quant',uty))): changed=True
            if add(('Quant',('Fork',uty,uty)),('Fork',('Quant',uty),('Quant',uty))): changed=True
        # dist full
        for uty in U:
            for vty in U:
                if add(('Quant',('Funty',uty,vty)),('Funty',('Quant',uty),('Quant',vty))): changed=True
                if add(('Quant',('Fork',uty,vty)),('Fork',('Quant',uty),('Quant',vty))): changed=True
        # leaf_fun, stem_fun, fork_leaf, fork_stem, fork_fork_*
        for uty in U:
            for vty in U:
                if add(LEAF,('Funty',uty,('Stem',uty))): changed=True
                if add(('Stem',uty),('Funty',vty,('Fork',uty,vty))): changed=True
                if add(('Fork',LEAF,uty),('Funty',vty,uty)): changed=True
                for wty in U:
                    if add(('Fork',('Stem',('Funty',uty,('Funty',vty,wty))),('Funty',uty,vty)),('Funty',uty,wty)): changed=True
                    if add(('Fork',('Fork',uty,vty),wty),('Funty',LEAF,uty)): changed=True
