VARS=[('Var',0),('Var',1)]
LEAF=('Leaf',)
def size(t):
    c=t[0]
    if c in ('Var','Leaf'): return 1
    if c in ('Stem','Quant','Asf'): return 1+size(t[1])
    return 1+size(t[1])+size(t[2])
def gen(N,vars_):
    levels={1:set(vars_+[LEAF])}; allset=set(levels[1])
    for s in range(2,N+1):
        cur=set()
        for u in ('Stem','Quant','Asf'):
            for t in allset:
                if size(t)+1==s: cur.add((u,t))
        for c in ('Fork','Funty'):
            for a in allset:
                for b in allset:
                    if size(a)+size(b)+1==s: cur.add((c,a,b))
        levels[s]=cur; allset|=cur
    return sorted(allset,key=lambda t:(size(t),t))
def lift_rec(t,k,n):
    c=t[0]
    if c=='Var': return ('Var', t[1]+n if k<=t[1] else t[1])
    if c=='Leaf': return LEAF
    if c=='Quant': return ('Quant',lift_rec(t[1],k+1,n))
    if c in ('Stem','Asf'): return (c,lift_rec(t[1],k,n))
    return (c,lift_rec(t[1],k,n),lift_rec(t[2],k,n))
