                if (R[ai]>>idx[('Asf',U[b])])&1==0:
                    R[ai]|=1<<idx[('Asf',U[b])]; changed=True
        for aa in quant_pairs:
            ai=idx[('Quant',aa)]; bits=R[idx[aa]]
