    if t[0]=='Stem': return ('Stem',lift_rec(t[1],k,n))
    if t[0]=='Fork': return ('Fork',lift_rec(t[1],k,n),lift_rec(t[2],k,n))
    if t[0]=='Funty': return ('Funty',lift_rec(t[1],k,n),lift_rec(t[2],k,n))
