def tstr(t):
    if t[0]=='v': return '?'+str(t[1])
    if t[0]=='Var': return 'V%d'%t[1]
    if t[0]=='Leaf': return 'L'
    if t[0] in ('Stem','Quant','Asf'): return t[0][0]+'('+tstr(t[1])+')'
    return ('K' if t[0]=='Fork' else 'F')+'('+tstr(t[1])+','+tstr(t[2])+')'
def prove(goal,s,depth):
    """generator of substitutions proving subtype S T"""
    global NODES
    NODES+=1
    if NODES>LIMIT: return
    if depth<=0: return
    S,T=subst(goal[0],s),subst(goal[1],s)
    ss=unify(S,T,s)
    if ss is not None: yield ss
    # target directed
    if T[0]=='Funty' and len(T)==3:
        U,W=T[1],T[2]
        # source directed
        if S[0]=='Leaf':
            # L1 forward: Stem U <: W
            yield from prove(('sub',('Stem',U),W),s,depth-1)
        elif S[0]=='Stem':
