import sys
sys.setrecursionlimit(1000000)
# Term: ('v',id) logic var; ('Var',n); ('Leaf',); ('Stem',a);('Fork',a,b);('Funty',a,b);('Quant',a);('Asf',a)
class Vars:
    def __init__(self): self.n=0
    def fresh(self): self.n+=1; return ('v',self.n)
VS=Vars()
Leaf=('Leaf',)
def is_var(t): return t[0]=='v' or t[0]=='Var'
def occurs(v,t):
    if t[0]=='v': return t[1]==v[1]
    if t[0] in ('Var','Leaf','C'): return False
    if t[0] in ('Stem','Quant','Asf'): return occurs(v,t[1])
    return occurs(v,t[1]) or occurs(v,t[2])
def subst(t,s):
    if not isinstance(t,tuple):
        print('BADSUBST',repr(t)); raise TypeError('bad term')
    if t[0]=='v':
        r=s.get(t[1],t)
        if not isinstance(r,tuple):
            print('BADMAP',t[1],repr(r)); raise TypeError('bad map')
        return r
    if t[0] in ('Var','Leaf','C'): return t
    if t[0] in ('Stem','Quant','Asf'): return (t[0],subst(t[1],s))
    return (t[0],subst(t[1],s),subst(t[2],s))
def unify(a,b,s):
    if not isinstance(a,tuple) or not isinstance(b,tuple):
        print('BADUNIFY',repr(a),repr(b)); raise TypeError('bad unify')
    a=subst(a,s); b=subst(b,s)
    if a[0]=='v' and b[0]=='v' and a[1]==b[1]: return s
    if a[0]=='v':
        if occurs(a,b): return None
        s=dict(s); s[a[1]]=b; return s
    if b[0]=='v':
        if occurs(b,a): return None
        s=dict(s); s[b[1]]=a; return s
    if a[0]!=b[0]: return None
    if a[0] in ('Var','Leaf','C'): return s if a==b else None
    if a[0] in ('Stem','Quant','Asf'): return unify(a[1],b[1],s)
    s=unify(a[1],b[1],s)
    if s is None: return None
    return unify(a[2],b[2],s)
def test(n,m): return n<=m
def relocate(i,k,n): return (n+i) if test(k,i) else i
def lift_rec(t,k,n):
    if not isinstance(t,tuple):
        print('BADLIFT',repr(t)); raise TypeError('bad lift')
    if t[0] in ('v','C'): return t
    if t[0]=='Var': return ('Var',relocate(t[1],k,n))
    if t[0]=='Leaf': return t
    if t[0]=='Stem': return ('Stem',lift_rec(t[1],k,n))
    if t[0]=='Fork': return ('Fork',lift_rec(t[1],k,n),lift_rec(t[2],k,n))
    if t[0]=='Funty': return ('Funty',lift_rec(t[1],k,n),lift_rec(t[2],k,n))
    if t[0]=='Quant': return ('Quant',lift_rec(t[1],k+1,n))
    if t[0]=='Asf': return ('Asf',lift_rec(t[1],k,n))
def insert_Var(N,i,k):
    if k<i: return ('Var',i-1)
    elif k==i: return lift_rec(N,0,k)  # lift k N
    else: return ('Var',i)
def subst_rec(t,N,k):
    if not isinstance(t,tuple):
        print('BADSUBREC',repr(t)); raise TypeError('bad subrec')
    if t[0] in ('v','C'): return t
    if t[0]=='Var': return insert_Var(N,t[1],k)
    if t[0]=='Leaf': return t
    if t[0]=='Stem': return ('Stem',subst_rec(t[1],N,k))
    if t[0]=='Fork': return ('Fork',subst_rec(t[1],N,k),subst_rec(t[2],N,k))
    if t[0]=='Funty': return ('Funty',subst_rec(t[1],N,k),subst_rec(t[2],N,k))
    if t[0]=='Quant': return ('Quant',subst_rec(t[1],N,k+1))
    if t[0]=='Asf': return ('Asf',subst_rec(t[1],N,k))
def subst0(t,N): return subst_rec(t,N,0)
def tsize(t):
    if t[0]=='v' or t[0] in ('Var','Leaf'): return 1
    if t[0] in ('Stem','Quant','Asf'): return 1+tsize(t[1])
    return 1+tsize(t[1])+tsize(t[2])
def tstr(t):
    if t[0]=='v': return '?'+str(t[1])
    if t[0]=='Var': return 'V'+str(t[1])
    if t[0]=='Leaf': return 'L'
    if t[0] in ('Stem','Quant','Asf'): return t[0][0]+'('+tstr(t[1])+')'
    return ('K' if t[0]=='Fork' else 'F')+'('+tstr(t[1])+','+tstr(t[2])+')'
# ground omega types (from reprs, now with Var if any; omega types have none)
reprs=[l.split('"')[1] for l in open('/tmp/reprs.txt') if '"' in l]
def parse(s,i=0):
    c=s[i]
    if c=='L': return Leaf,i+1
    if c=='V': return ('Var',0),i+1  # not used
    if c=='S':
        a,i2=parse(s,i+2); return ('Stem',a),i2+1
    if c=='Q':
        a,i2=parse(s,i+2); return ('Quant',a),i2+1
    if c=='A':
        a,i2=parse(s,i+2); return ('Asf',a),i2+1
    if c in 'KF':
        a,i2=parse(s,i+2); b,i3=parse(s,i2+1)
        return (('Fork' if c=='K' else 'Funty'),a,b),i3+1
q0f=('Funty',('Var',0),('Var',1))  # body Funty Var0 Var1 (open)
# parse omega types
omega21=parse(reprs[0])[0]
omega22_ty=parse(reprs[1])[0]
omega22_left=parse(reprs[2])[0]
omega22_right=parse(reprs[3])[0]
