print('omega21 okay',omega21==('Fork',Leaf,('Stem',('Stem',A0))))
print('omega22_ty root',omega22_ty[0],omega22_ty[1][1]==omega22_left,omega22_ty[2]==omega22_right)

import sys, re, itertools
sys.setrecursionlimit(100000)

# Term representation
# ('v', id) variable; ('C','Leaf'); ('Fork',a,b); ('Stem',a); ('Funty',a,b); ('Quant',a); ('Asf',a)
# constants as ground terms via parser

class Vars:
    def __init__(self): self.n=0
    def fresh(self):
        self.n+=1; return ('v',self.n)
VS=Vars()

def parse(s,i=0):
    if i>=len(s): raise ValueError('eof')
    c=s[i]
    if c=='L': return ('C','Leaf'), i+1
    if c=='V':
        # parse digits after V? repr uses just V; no de Bruijn indices. Use unique constant V.
        return ('C','Var'), i+1
    if c=='S':
        assert s[i+1]=='('
        a,i2=parse(s,i+2); assert s[i2]==')'; return ('Stem',a), i2+1
    if c=='Q':
        assert s[i+1]=='('
        a,i2=parse(s,i+2); assert s[i2]==')'; return ('Quant',a), i2+1
    if c=='A':
        assert s[i+1]=='('
        a,i2=parse(s,i+2); assert s[i2]==')'; return ('Asf',a), i2+1
    if c in 'KF':
        assert s[i+1]=='('
        a,i2=parse(s,i+2); assert s[i2]==','; b,i3=parse(s,i2+1); assert s[i3]==')'
        return (('Fork' if c=='K' else 'Funty'),a,b), i3+1
    raise ValueError(s[i:])

def walk(t, f):
    if t[0]=='v': return f(t)
    if t[0] in ('C',): return t
    if t[0] in ('Stem','Quant','Asf'): return (t[0], walk(t[1],f))
    if t[0] in ('Fork','Funty'): return (t[0], walk(t[1],f), walk(t[2],f))
    return t

def subst(t, s):
    if t[0]=='v':
        return s.get(t[1], t)
    if t[0]=='C': return t
    if t[0] in ('Stem','Quant','Asf'): return (t[0], subst(t[1],s))
    if t[0] in ('Fork','Funty'): return (t[0], subst(t[1],s), subst(t[2],s))
    return t

def occurs(v,t):
    if t[0]=='v': return t[1]==v[1]
    if t[0]=='C': return False
    if t[0] in ('Stem','Quant','Asf'): return occurs(v,t[1])
    if t[0] in ('Fork','Funty'): return occurs(v,t[1]) or occurs(v,t[2])
    return False

def unify(a,b,s):
    a=subst(a,s); b=subst(b,s)
    if a[0]=='v' and b[0]=='v' and a[1]==b[1]: return s
    if a[0]=='v':
        if occurs(a,b): return None
        s=dict(s); s[a[1]]=b; return s
    if b[0]=='v':
        if occurs(b,a): return None
        s=dict(s); s[b[1]]=a; return s
    if a[0]!=b[0]: return None
    if a[0]=='C': return s if a==b else None
    if a[0] in ('Stem','Quant','Asf'):
        return unify(a[1],b[1],s)
    if a[0] in ('Fork','Funty'):
        s=unify(a[1],b[1],s)
        if s is None: return None
        return unify(a[2],b[2],s)
    return None

def term_size(t):
    if t[0]=='v' or t[0]=='C': return 1
    if t[0] in ('Stem','Quant','Asf'): return 1+term_size(t[1])
    return 1+term_size(t[1])+term_size(t[2])

# Ground types
Leaf=('C','Leaf')
q0=('Funty',Leaf,Leaf)
W20=('Funty',q0,q0)
G0=('Funty',W20,q0)
A0=('Fork',('Stem',('Stem',Leaf)),('Stem',Leaf))
tail=('Fork',Leaf,A0)
omega21=('Fork',Leaf,('Stem',('Stem',A0)))  # check shape
omega22_right=('Fork',Leaf,tail)
# omega22_left from repr file line 3
reprs=[l.split('"')[1] for l in open('/tmp/reprs.txt') if '"' in l]
# order: omega21, omega22_ty, omega22_left, omega22_right, tail, T6,T7,M
