                for s2 in prove(('sub',S[2],T[2]),s1,depth-1):
                    yield s2
        if T[0]=='Asf':
            # to_asf trans: S <: Asf Y if S <: Y
            yield from prove(('sub',S,T[1]),s,depth-1)
            if S[0]=='Asf':
                yield from prove(('sub',S[1],T[1]),s,depth-1)
        if T[0]=='Quant':
            if S[0]=='Quant':
                yield from prove(('sub',S[1],T[1]),s,depth-1)
                # sub_inst exact: Quant ty <: subst ty u
                ty=S[1]; u=VS.fresh()
                ss=unify(T,subst0(ty,u),s)
                if ss is not None: yield ss
            # sub_lift exact
            ss=unify(T,('Quant',lift(S,1)),s)
            if ss is not None: yield ss
        if T[0]=='Var':
            if S[0]=='Quant':
                ty=S[1]; u=VS.fresh()
                ss=unify(T,subst0(ty,u),s)
                if ss is not None: yield ss
        # qstem/qfork/qasf exact
        if T[0]=='Stem' and S[0]=='Quant' and S[1][0]=='Stem':
            ss=unify(T,('Stem',('Quant',S[1][1])),s)
            if ss is not None: yield ss
        if T[0]=='Fork' and S[0]=='Quant' and S[1][0]=='Fork':
            ss=unify(T,('Fork',('Quant',S[1][1]),('Quant',S[1][2])),s)
            if ss is not None: yield ss
        if T[0]=='Asf' and S[0]=='Quant' and S[1][0]=='Asf':
            ss=unify(T,('Asf',('Quant',S[1][1])),s)
            if ss is not None: yield ss
    return
def tryg(name,S,T,d,limit=2000000):
    global NODES,LIMIT
    NODES=0; LIMIT=limit
    ok=False
    for s in prove(('sub',S,T),{},d):
        ok=True; break
    print(name,'OK' if ok else 'no','nodes',NODES,'d',d, flush=True)
    return ok
if __name__=='__main__':
