def prove(goal,s,depth):
    """generator of substitutions proving subtype S T"""
    global NODES
    NODES+=1
    if NODES>LIMIT: return
    if depth<=0: return
    S,T=subst(goal[1],s),subst(goal[2],s)
    ss=unify(S,T,s)
    if ss is not None: yield ss
    # target directed
    if T[0]=='Funty' and len(T)==3:
        U,W=T[1],T[2]
        # source directed
        if S[0]=='Leaf':
            # L1 forward: Stem U <: W
            yield from prove(('sub',('Stem',U),W),s,depth-1)
        elif S[0]=='Stem':
            # L2 forward: Fork X U <: W
            yield from prove(('sub',('Fork',S[1],U),W),s,depth-1)
        elif S[0]=='Fork' and S[1][0]=='Leaf' and S[1]==Leaf:
            # L3 forward: Y <: W
            yield from prove(('sub',S[2],W),s,depth-1)
        elif S[0]=='Fork' and S[1][0]=='Stem':
            X=S[1][1]; Y=S[2]; V=VS.fresh()
            # reverse direction only (sound, incomplete): X<:F U (F V W), Y<:F U V
            for s1 in prove(('sub',Y,('Funty',U,V)),s,depth-1):
                VV=subst(V,s1)
                for s2 in prove(('sub',X,('Funty',U,('Funty',VV,W))),s1,depth-1):
                    yield s2
        elif S[0]=='Fork' and S[1][0]=='Fork':
            X,Y=S[1][1],S[1][2]; Z=S[2]
            # atomic fork_fork rules
            # leaf: target Funty Leaf u
            ss2=unify(U,Leaf,s)
            if ss2 is not None:
                yield from prove(('sub',X,W),ss2,depth-1)  # sub_fork_fork_leaf: X <: W with target Funty Leaf W? rule: Fork(Fork u v) w <: Funty Leaf u
            # stem: Fork(Fork u (Funty v1 v2)) w <: Funty (Stem v1) v2
            v1=VS.fresh(); v2=VS.fresh()
            ss2=unify(T,('Funty',('Stem',v1),v2),s)
            if ss2 is not None:
                ss3=unify(S,('Fork',('Fork',X[1],('Funty',v1,v2)),Y),ss2)
                if ss3 is not None:
                    yield ss3
            # fork: Fork(Fork u v)(Funty w1(Funty w2 w3)) <: Funty (Fork w1 w2) w3
            w1=VS.fresh(); w2=VS.fresh(); w3=VS.fresh()
            ss2=unify(T,('Funty',('Fork',w1,w2),w3),s)
            if ss2 is not None:
                ss3=unify(S,('Fork',('Fork',X,Y),('Funty',w1,('Funty',w2,w3))),ss2)
                if ss3 is not None:
                    yield ss3
        elif S[0]=='Funty':
            A,B=S[1],S[2]
            for s1 in prove(('sub',U,A),s,depth-1):
                for s2 in prove(('sub',B,W),s1,depth-1):
                    yield s2
        elif S[0]=='Asf' and S[1][0]=='Funty':
            A,B=S[1][1],S[1][2]
            for s1 in prove(('sub',U,A),s,depth-1):
                for s2 in prove(('sub',B,W),s1,depth-1):
                    yield s2
        # source Quant: dist, inst
        if S[0]=='Quant':
            # dist if inner Funty: S=Quant(Funty u v) <: Funty (Quant u)(Quant v) <: T
            if S[1][0]=='Funty':
                u1,v1=S[1][1],S[1][2]
                T0=('Funty',('Quant',u1),('Quant',v1))
                yield from prove(('sub',T0,T),s,depth-1)
            # inst: Quant ty <: subst ty u <: T
            ty=S[1]; u=VS.fresh()
            T0=subst0(ty,u)
            yield from prove(('sub',T0,T),s,depth-1)
    elif T[0]=='Stem' and len(T)==2:
        if S[0]=='Stem':
            yield from prove(('sub',S[1],T[1]),s,depth-1)
        if S[0]=='Quant' and S[1][0]=='Stem':
            ss2=unify(T[1],('Quant',S[1][1]),s)
            if ss2 is not None: yield ss2
    elif T[0]=='Fork' and len(T)==3:
        if S[0]=='Fork':
            for s1 in prove(('sub',S[1],T[1]),s,depth-1):
                for s2 in prove(('sub',S[2],T[2]),s1,depth-1):
                    yield s2
        if S[0]=='Quant' and S[1][0]=='Fork':
            for s1 in prove(('sub',S[1][1],T[1]),s,depth-1):
                for s2 in prove(('sub',S[1][2],T[2]),s1,depth-1):
                    yield s2
    elif T[0]=='Asf' and len(T)==2:
        if S[0]=='Asf':
            yield from prove(('sub',S[1],T[1]),s,depth-1)
        if S[0]=='Quant' and S[1][0]=='Asf':
            ss2=unify(T[1],('Quant',S[1][1]),s)
            if ss2 is not None: yield ss2
        # to_asf
        ss2=unify(T[1],S,s)
        if ss2 is not None: yield ss2
        # to_asf then asf/other: S <: T[1] suffices (S <: Asf S <: Asf T[1])
        if depth>2:
            yield from prove(('sub',S,T[1]),s,depth-2)
    elif T[0]=='Quant' and len(T)==2:
        if S[0]=='Quant':
            yield from prove(('sub',S[1],T[1]),s,depth-1)
            # inst from quant source
            ty=S[1]; u=VS.fresh()
            ss2=unify(subst0(ty,u),T,s)
            if ss2 is not None: yield ss2
        # lift
        ss2=unify(T,('Quant',lift(S,1)),s)
        if ss2 is not None: yield ss2
        # lift then trans
        if depth>2:
            yield from prove(('sub',('Quant',lift(S,1)),T),s,depth-2)
    elif T[0]=='Var' and len(T)==2:
        if S[0]=='Quant':
            ty=S[1]; u=VS.fresh()
            ss2=unify(subst0(ty,u),T,s)
            if ss2 is not None: yield ss2
    # generic trans with candidate intermediates
    if depth>4:
        for mid in candidates(S,T):
            for s1 in prove(('sub',S,mid),s,depth-3):
                S2=subst(mid,s1)
                for s2 in prove(('sub',S2,T),s1,depth-3):
                    yield s2
    # recursion atomic on source omega2 and target matching
    ss2=unify(S,omega2,s)
    if ss2 is not None:
        # try rec with q = quant k (Funty uty vty) for k=0..3
        for k in range(0,4):
            uty=VS.fresh(); vty=VS.fresh()
            q=quant(k,('Funty',uty,vty))
            Trec=('Funty',omega2,('Funty',('Funty',q,q),q))
            ss3=unify(T,Trec,ss2)
            if ss3 is not None:
                yield ss3
